<template><div class="editor"><div class="toolbar" role="toolbar" aria-label="Markdown工具栏"><button v-for="tool in tools" :key="tool.label" type="button" :title="tool.label" @click="insert(tool)">{{tool.label}}</button><label>导入<input type="file" accept=".md,.markdown,.txt" @change="importFile" /></label><button type="button" @click="download">导出</button></div><div class="editor-panels"><div><label class="pane-label">Markdown</label><textarea ref="input" :value="modelValue" maxlength="20000" spellcheck="false" @input="$emit('update:modelValue',$event.target.value)" @keydown="keydown" @scroll="syncScroll" /></div><div ref="preview" class="preview"><label class="pane-label">实时预览</label><MarkdownView :value="modelValue" /></div></div><div class="editor-foot"><span>{{modelValue.length}} / 20000 字</span><label><input v-model="sync" type="checkbox" /> 同步滚动</label><span>Ctrl+B / I / K · Tab 缩进 · Ctrl+S 保存</span></div></div></template>
<script setup>
import { ref, nextTick } from 'vue'
import MarkdownView from './MarkdownView.vue'
const props=defineProps({modelValue:{type:String,default:''}})
const emit=defineEmits(['update:modelValue','save'])
const input=ref(null),preview=ref(null),sync=ref(true)
const tools=[{label:'H1',prefix:'# ',line:true},{label:'H2',prefix:'## ',line:true},{label:'H3',prefix:'### ',line:true},{label:'粗体',prefix:'**',suffix:'**'},{label:'斜体',prefix:'_',suffix:'_'},{label:'删除线',prefix:'~~',suffix:'~~'},{label:'链接',prefix:'[',suffix:'](https://)'},{label:'图片',prefix:'![',suffix:'](https://)'},{label:'引用',prefix:'> ',line:true},{label:'无序列表',prefix:'- ',line:true},{label:'有序列表',prefix:'1. ',line:true},{label:'任务',prefix:'- [ ] ',line:true},{label:'代码',prefix:'`',suffix:'`'},{label:'代码块',prefix:'\n```\n',suffix:'\n```\n'},{label:'表格',prefix:'\n| 列1 | 列2 |\n| --- | --- |\n| 内容 | 内容 |\n'},{label:'分割线',prefix:'\n---\n'}]
function insert(t){const el=input.value;const start=el.selectionStart,end=el.selectionEnd;const a=t.line?props.modelValue.lastIndexOf('\n',start-1)+1:start;const text=props.modelValue.slice(start,end)||(!t.line&&t.suffix?'文字':'');const value=props.modelValue.slice(0,a)+t.prefix+(a<start?props.modelValue.slice(a,start):'')+text+(t.suffix||'')+props.modelValue.slice(end);emit('update:modelValue',value.slice(0,20000));nextTick(()=>{el.focus();el.setSelectionRange(a+t.prefix.length,a+t.prefix.length+text.length)})}
function keydown(e){if(e.key==='Tab'){e.preventDefault();insert({prefix:'  '});return}if(!(e.ctrlKey||e.metaKey))return;const key=e.key.toLowerCase();if(['b','i','k','s'].includes(key)){e.preventDefault();if(key==='s')emit('save');else insert(tools.find(t=>t.label===({b:'粗体',i:'斜体',k:'链接'}[key])))}}
function syncScroll(){const a=input.value,b=preview.value;if(sync.value&&a.scrollHeight>a.clientHeight)b.scrollTop=a.scrollTop/(a.scrollHeight-a.clientHeight)*(b.scrollHeight-b.clientHeight)}
async function importFile(e){const file=e.target.files?.[0];if(file&&file.size<=80000)emit('update:modelValue',(await file.text()).slice(0,20000));e.target.value=''}
function download(){const url=URL.createObjectURL(new Blob([props.modelValue],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='公告.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<style scoped>.editor{border:1px solid var(--border);border-radius:10px;overflow:hidden}.toolbar{display:flex;flex-wrap:wrap;gap:4px;padding:8px;background:var(--bg)}.toolbar button,.toolbar label{border:1px solid var(--border);border-radius:5px;background:var(--bg-card);color:var(--text);padding:6px 9px;font-size:12px;cursor:pointer}.toolbar input{display:none}.editor-panels{display:grid;grid-template-columns:1fr 1fr}.editor-panels>div{min-width:0}.pane-label{display:block;padding:8px;font-size:12px;color:var(--text-dim);position:sticky;top:0;background:var(--bg-card)}textarea{width:100%;height:360px;box-sizing:border-box;resize:vertical;border:0;border-right:1px solid var(--border);background:var(--bg);color:var(--text);padding:12px;line-height:1.8;font:14px/1.8 monospace}.preview{height:396px;overflow:auto;padding:0 12px}.editor-foot{display:flex;flex-wrap:wrap;gap:12px;padding:8px;font-size:11px;color:var(--text-dim)}@media(max-width:650px){.editor-panels{grid-template-columns:1fr}textarea{height:230px}.preview{height:250px;border-top:1px solid var(--border)}}</style>
